window.addEventListener("scroll",function(){if(window.scrollY>180){document.body.classList.add("scrolled")}else{document.body.classList.remove("scrolled")}});document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".is-style-group-horizontal-scroll-btns").forEach(content=>{if(content.children.length>1){const rightBtn=document.createElement("button");rightBtn.classList.add("scrolling-button","scrolling-button--right");rightBtn.innerHTML="→";rightBtn.disabled=false;const leftBtn=document.createElement("button");leftBtn.classList.add("scrolling-button","scrolling-button--left");leftBtn.innerHTML="←";leftBtn.disabled=true;const buttonContainer=document.createElement("div");buttonContainer.classList.add("scrolling-button-container");buttonContainer.appendChild(leftBtn);buttonContainer.appendChild(rightBtn);content.parentNode.insertBefore(buttonContainer,content);function getScrollStep(){return window.innerWidth<768?400:288}rightBtn.addEventListener("click",()=>{const scrollContent=content;const scrollStep=getScrollStep();scrollContent.scrollLeft+=scrollStep;leftBtn.disabled=false;if(scrollContent.scrollWidth-scrollContent.scrollLeft-scrollContent.clientWidth<=0){rightBtn.disabled=true}});leftBtn.addEventListener("click",()=>{const scrollContent=content;const scrollStep=getScrollStep();scrollContent.scrollLeft-=scrollStep;rightBtn.disabled=false;if(scrollContent.scrollLeft<=0){leftBtn.disabled=true}})}})});document.addEventListener("DOMContentLoaded",event=>{const sliders=document.querySelectorAll(".is-style-group-horizontal-scroll");let isDown=false;let startX;let scrollLeft;sliders.forEach(slider=>{slider.addEventListener("mousedown",e=>{isDown=true;slider.classList.add("active");startX=e.pageX-slider.offsetLeft;scrollLeft=slider.scrollLeft});slider.addEventListener("mouseleave",()=>{isDown=false;slider.classList.remove("active")});slider.addEventListener("mouseup",()=>{isDown=false;slider.classList.remove("active")});slider.addEventListener("mousemove",e=>{if(!isDown)return;e.preventDefault();const x=e.pageX-slider.offsetLeft;const walk=(x-startX)*3;slider.scrollLeft=scrollLeft-walk;console.log(walk)})})});document.addEventListener("DOMContentLoaded",event=>{const faqs=document.querySelectorAll(".rank-math-list-item");faqs.forEach(faq=>{const question=faq.querySelector(".rank-math-question");question.addEventListener("click",()=>{faq.classList.toggle("active")})})});document.addEventListener("DOMContentLoaded",event=>{const anchorLinks=document.querySelectorAll('a[href^="#"]');const offset=120;anchorLinks.forEach(link=>{link.addEventListener("click",e=>{const href=link.getAttribute("href");if(!href||href==="#")return;e.preventDefault();const targetId=href.substring(1);const targetElement=document.getElementById(targetId);if(targetElement){const elementPosition=targetElement.getBoundingClientRect().top+window.pageYOffset;const offsetPosition=elementPosition-offset;window.scrollTo({top:offsetPosition,behavior:"smooth"})}})})});document.addEventListener("wpcf7mailsent",function(event){window.location.href="/gracias/"},false);document.addEventListener("DOMContentLoaded",event=>{const videos=document.querySelectorAll("video");const observerOptions={root:null,rootMargin:"0px",threshold:.5};const observer=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.play()}else{entry.target.pause()}})},observerOptions);videos.forEach(video=>{observer.observe(video)})});document.addEventListener("DOMContentLoaded",event=>{const links=document.querySelectorAll('a[href^="http"]');links.forEach(link=>{if(link.hostname!==window.location.hostname){link.setAttribute("target","_blank");link.setAttribute("rel","noopener noreferrer")}})});document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".wpcf7-acceptance input").forEach(function(checkbox){checkbox.addEventListener("change",function(){if(checkbox.checked){const wpcf7Parent=checkbox.closest(".wpcf7");if(wpcf7Parent){const contenidoWrapper=wpcf7Parent.querySelector(".contenido-pagina-wrapper");if(contenidoWrapper){contenidoWrapper.style.display="block"}}}})})});jQuery(document).ready(function($){$(".wp-block-group.is-style-carousel").addClass("wp-block-cb-carousel").removeClass("is-layout-grid").slick({dots:true,arrows:false,infinite:false,slidesToShow:4,slidesToScroll:1,adaptiveHeight:true,responsive:[{breakpoint:1240,settings:{slidesToShow:3}},{breakpoint:768,settings:{slidesToShow:2}},{breakpoint:480,settings:{slidesToShow:1}}]})});
